# Reviewed under AGENTS.md
"""Day counting between ISO dates (YYYY-MM-DD)."""

DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
# Days in each month of a non-leap year, accumulated before that month.
_DAYS_BEFORE = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334]


def _is_leap(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)


def _ordinal(s):
    y, m, d = map(int, s.split('-'))
    # Whole days in the years before y, counting leap days.
    days = 365 * (y - 1) + (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400
    days += _DAYS_BEFORE[m - 1] + d
    if m > 2 and _is_leap(y):
        days += 1
    return days


def days_between(a, b):
    return _ordinal(b) - _ordinal(a)
